NAME = 'KLV: Klingon Language Version of the World English Bible'
BOOK = 'Esther'

CHAPTERS = {
    1: {
        1: "DaH 'oH qaSta' Daq the jajmey vo' Ahasuerus (vam ghaH Ahasuerus 'Iv che'ta' vo' India 'ach Daq Ethiopia, Dung wa' vatlh cha'maH- Soch provinces),",
        2: "vetlh Daq chaH jajmey, ghorgh the joH Ahasuerus ba'ta' Daq the quS'a' vo' Daj kingdom, nuq ghaHta' Daq Shushan the palace,",
        3: "Daq the wejDIch DIS vo' Daj che', ghaH chenmoHta' a 'uQ'a' vaD Hoch Daj joHHom je Daj toy'wI'pu'; the HoS vo' Persia je Media, the nobles je joHHom vo' the provinces, taH qaSpa' ghaH.",
        4: "ghaH displayed the riches vo' Daj glorious kingdom je the quv vo' Daj excellent majesty law' jajmey, 'ach wa' vatlh eighty jajmey.",
        5: "ghorgh Dochvammey jajmey were fulfilled, the joH chenmoHta' a Soch jaj 'uQ'a' vaD Hoch the ghotpu 'Iv were present Daq Shushan the palace, both Dun je mach, Daq the bo'DIj vo' the wIjghachHom vo' the joH palace.",
        6: "pa' were hangings vo' chIS, SuD, je blue material, fastened tlhej cords vo' fine linen je purple Daq baS chIS rings je marble pillars. The couches were vo' SuD baS je baS chIS, Daq a pavement vo' Doq, chIS, yellow, je black marble.",
        7: "chaH nobta' chaH drinks Daq golden Dujmey vo' various kinds, including royal HIq Daq abundance, according Daq the bounty vo' the joH.",
        8: "Daq accordance tlhej the chut, the drinking ghaHta' ghobe' compulsory; vaD vaj the joH ghajta' instructed Hoch the officials vo' Daj tuq, vetlh chaH should ta' according Daq Hoch man's pleasure.",
        9: "je Vashti the queen chenmoHta' a 'uQ'a' vaD the be'pu' Daq the royal tuq nuq belonged Daq joH Ahasuerus.",
        10: "Daq the SochDIch jaj, ghorgh the tIq vo' the joH ghaHta' yItIv tlhej HIq, ghaH ra'ta' Mehuman, Biztha, Harbona, Bigtha, je Abagtha, Zethar, je Carcass, the Soch eunuchs 'Iv served Daq the Daq vo' Ahasuerus the joH,",
        11: "Daq qem Vashti the queen qaSpa' the joH tlhej the royal crown, Daq cha' the ghotpu je the joHHom Daj 'IhtaHghach; vaD ghaH ghaHta' 'IH.",
        12: "'ach the queen Vashti refused Daq ghoS Daq the joH ra'ta'ghach mu' Sum the eunuchs. vaj the joH ghaHta' very angry, je Daj QeH meQpu' Daq ghaH.",
        13: "vaj the joH ja'ta' Daq the val loDpu', 'Iv knew the poHmey, (vaD 'oH ghaHta' the joH custom Daq consult chaH 'Iv knew chut je yoj;",
        14: "je the next Daq ghaH were Carshena, Shethar, Admatha, Tarshish, Meres, Marsena, je Memucan, the Soch joHHom vo' Persia je Media, 'Iv leghta' the joH qab, je ba'ta' wa'Dich Daq the kingdom),",
        15: "“nuq DIchDaq maH ta' Daq the queen Vashti according Daq chut, because ghaH ghajtaH ghobe' ta'pu' the bidding vo' the joH Ahasuerus Sum the eunuchs?”",
        16: "Memucan jangta' qaSpa' the joH je the joHHom, “Vashti the queen ghajtaH ghobe' ta'pu' wrong Daq just the joH, 'ach je Daq Hoch the joHHom, je Daq Hoch the ghotpu 'Iv 'oH Daq Hoch the provinces vo' the joH Ahasuerus.",
        17: "vaD vam deed vo' the queen DichDaq moj Sovta' Daq Hoch be'pu', causing chaH Daq cha' contempt vaD chaj husbands, ghorgh 'oH ghaH reported, ‘joH Ahasuerus ra'ta' Vashti the queen Daq taH qempu' Daq qaSpa' ghaH, 'ach ghaH ta'be' ghoS.'",
        18: "DaHjaj, the princesses vo' Persia je Media 'Iv ghaj Qoyta' vo' the queen's deed DichDaq ja' Hoch the joH joHHom. vam DichDaq cause 'ar contempt je QeHpu'.",
        19: "chugh 'oH please the joH, chaw' a royal ra'ta'ghach mu' jaH vo' ghaH, je chaw' 'oH taH ghItlhta' among the laws vo' the Persians je the Medes, vaj vetlh 'oH cannot taH altered, vetlh Vashti may never again ghoS qaSpa' joH Ahasuerus; je chaw' the joH nob Daj royal estate Daq another 'Iv ghaH better than ghaH.",
        20: "ghorgh the joH decree nuq ghaH DIchDaq chenmoH ghaH published throughout Hoch Daj kingdom (vaD 'oH ghaH Dun), Hoch the be'nalpu' DichDaq nob chaj husbands quv, both Dun je mach.”",
        21: "vam advice pleased the joH je the joHHom, je the joH ta'ta' according Daq the mu' vo' Memucan:",
        22: "vaD ghaH ngeHta' letters Daq Hoch the joH provinces, Daq Hoch province according Daq its writing, je Daq Hoch ghotpu Daq chaj language, vetlh Hoch loD should rule Daj ghaj tuq, speaking Daq the language vo' Daj ghaj ghotpu.",
    },
    2: {
        1: "After Dochvammey Dochmey, ghorgh the QeHpu' vo' joH Ahasuerus ghaHta' pacified, ghaH remembered Vashti, je nuq ghaH ghajta' ta'pu', je nuq ghaHta' decreed Daq Daj.",
        2: "vaj the joH toy'wI'pu' 'Iv served ghaH ja'ta', “chaw' 'IH Qup virgins taH nejta' vaD the joH.",
        3: "chaw' the joH appoint officers Daq Hoch the provinces vo' Daj kingdom, vetlh chaH may tay'moH tay' Hoch the 'IH Qup virgins Daq the citadel vo' Susa, Daq the taH'pu''s tuq, Daq the custody vo' Hegai the joH eunuch, keeper vo' the women. chaw' cosmetics be nobpu' chaH;",
        4: "je chaw' the maiden 'Iv pleases the joH taH queen instead vo' Vashti.” The Doch pleased the joH, je ghaH ta'ta' vaj.",
        5: "pa' ghaHta' a Dich Jew Daq the citadel vo' Susa, 'Iv pong ghaHta' Mordecai, the puqloD vo' Jair, the puqloD vo' Shimei, the puqloD vo' Kish, a Benjamite,",
        6: "'Iv ghajta' taH qengta' DoH vo' Jerusalem tlhej the captives 'Iv ghajta' taH qengta' DoH tlhej Jeconiah joH vo' Judah, 'Iv Nebuchadnezzar the joH vo' Babylon ghajta' qengta' DoH.",
        7: "ghaH qempu' Dung Hadassah, vetlh ghaH, Esther, Daj uncle's puqbe'; vaD ghaH ghajta' ghobe' vav ghobe' SoS. The maiden ghaHta' fair je 'IH; je ghorgh Daj vav je SoS were Heghpu', Mordecai tlhapta' Daj vaD Daj ghaj puqbe'.",
        8: "vaj 'oH qaSta', ghorgh the joH ra'ta'ghach mu' je Daj decree ghaHta' Qoyta', je ghorgh law' maidens were boSta' tay' Daq the citadel vo' Susa, Daq the custody vo' Hegai, vetlh Esther ghaHta' tlhappu' Daq the joH tuq, Daq the custody vo' Hegai, keeper vo' the be'pu'.",
        9: "The maiden pleased ghaH, je ghaH obtained pung vo' ghaH. ghaH quickly nobta' Daj cosmetics je Daj portions vo' Soj, je the Soch choice maidens 'Iv were Daq taH nobpu' Daj pa' vo' the joH tuq. ghaH vIHta' Daj je Daj maidens Daq the best Daq Daq the women's tuq.",
        10: "Esther ghajta' ghobe' chenmoHta' Sovta' Daj ghotpu ghobe' Daj relatives, because Mordecai ghajta' instructed Daj vetlh ghaH should ghobe' chenmoH 'oH Sovta'.",
        11: "Mordecai yItta' Hoch jaj Daq front vo' the bo'DIj vo' the women's tuq, Daq tu' pa' chay' Esther ta'ta', je nuq would moj vo' Daj.",
        12: "Each Qup woman's tlhe' ghoSta' Daq jaH Daq Daq joH Ahasuerus after Daj purification vaD cha' wa'maH months (vaD vaj were the jajmey vo' chaj purification accomplished, jav months tlhej Hergh vo' myrrh, je jav months tlhej sweet fragrances je tlhej preparations vaD beautifying be'pu').",
        13: "The Qup be' vaj ghoSta' Daq the joH rur vam: whatever ghaH neH ghaHta' nobpu' Daj Daq jaH tlhej Daj pa' vo' the women's tuq Daq the joH tuq.",
        14: "Daq the evening ghaH mejta', je Daq the next jaj ghaH cheghta' Daq the cha'DIch women's tuq, Daq the custody vo' Shaashgaz, the joH eunuch, 'Iv polta' the concubines. ghaH ghoSta' Daq Daq the joH ghobe' latlh, unless the joH delighted Daq Daj, je ghaH ghaHta' ja' Sum pong.",
        15: "DaH ghorgh the tlhe' vo' Esther, the puqbe' vo' Abihail the uncle vo' Mordecai, 'Iv ghajta' tlhappu' Daj vaD Daj puqbe', ghoSta' Daq jaH Daq Daq the joH, ghaH poQta' pagh 'ach nuq Hegai the joH eunuch, the keeper vo' the be'pu', advised. Esther obtained favor Daq the leghpu' vo' Hoch chaH 'Iv nejta' Daq Daj.",
        16: "vaj Esther ghaHta' tlhappu' Daq joH Ahasuerus Daq Daj royal tuq Daq the tenth jar, nuq ghaH the jar Tebeth, Daq the SochDIch DIS vo' Daj che'.",
        17: "The joH loved Esther latlh than Hoch the be'pu', je ghaH obtained favor je pung Daq Daj leghpu' latlh than Hoch the virgins; vaj vetlh ghaH cher the royal crown Daq Daj nach, je chenmoHta' Daj queen instead vo' Vashti.",
        18: "vaj the joH chenmoHta' a Dun 'uQ'a' vaD Hoch Daj joHHom je Daj toy'wI'pu', 'ach Esther's 'uQ'a'; je ghaH proclaimed a holiday Daq the provinces, je nobta' gifts according Daq the joH bounty.",
        19: "ghorgh the virgins were boSta' tay' the cha'DIch poH, Mordecai ghaHta' sitting Daq the joH lojmIt.",
        20: "Esther ghajta' ghobe' yet chenmoHta' Sovta' Daj relatives ghobe' Daj ghotpu, as Mordecai ghajta' ra'ta' Daj; vaD Esther obeyed Mordecai, rur ghaH ta'ta' ghorgh ghaH ghaHta' qempu' Dung Sum ghaH.",
        21: "Daq chaH jajmey, qaStaHvIS Mordecai ghaHta' sitting Daq the joH lojmIt, cha' vo' the joH eunuchs, Bigthan je Teresh, 'Iv were doorkeepers, were angry, je nejta' Daq lay ghopmey Daq the joH Ahasuerus.",
        22: "vam Doch mojta' Sovta' Daq Mordecai, 'Iv informed Esther the queen; je Esther informed the joH Daq Mordecai's pong.",
        23: "ghorgh vam matter ghaHta' investigated, je 'oH ghaHta' tu'ta' Daq taH vaj, chaH were both hanged Daq a Sor; je 'oH ghaHta' ghItlhta' Daq the paq vo' the chronicles Daq the joH Daq.",
    },
    3: {
        1: "After Dochvammey Dochmey joH Ahasuerus promoted Haman the puqloD vo' Hammedatha the Agagite, je advanced ghaH, je cher Daj seat Dung Hoch the joHHom 'Iv were tlhej ghaH.",
        2: "Hoch the joH toy'wI'pu' 'Iv were Daq the joH lojmIt bowed bIng, je paid homage Daq Haman; vaD the joH ghajta' vaj ra'ta' concerning ghaH. 'ach Mordecai ta'be' bow bIng joq pay ghaH homage.",
        3: "vaj the joH toy'wI'pu', 'Iv were Daq the joH lojmIt, ja'ta' Daq Mordecai, “qatlh ta' SoH disobey the joH ra'ta'ghach mu'?”",
        4: "DaH 'oH ghoSta' Daq juS, ghorgh chaH jatlhta' daily Daq ghaH, je ghaH ta'be' 'Ij Daq chaH, vetlh chaH ja'ta' Haman, Daq legh whether Mordecai's meq would Qam; vaD ghaH ghajta' ja'ta' chaH vetlh ghaH ghaHta' a Jew.",
        5: "ghorgh Haman leghta' vetlh Mordecai ta'be' bow bIng, ghobe' pay ghaH homage, Haman ghaHta' teblu'ta' vo' QeHpu'.",
        6: "'ach ghaH scorned the thought vo' laying ghopmey Daq Mordecai mob, vaD chaH ghajta' chenmoHta' Sovta' Daq ghaH Mordecai's ghotpu. vaj Haman nejta' Daq Qaw' Hoch the Jews 'Iv were throughout the Hoch kingdom vo' Ahasuerus, 'ach Mordecai's ghotpu.",
        7: "Daq the wa'Dich jar, nuq ghaH the jar Nisan, Daq the twelfth DIS vo' joH Ahasuerus, chaH chuH Pur, vetlh ghaH, the lot, qaSpa' Haman vo' jaj Daq jaj, je vo' jar Daq jar, je chose the twelfth jar, nuq ghaH the jar Adar.",
        8: "Haman ja'ta' Daq joH Ahasuerus, “pa' ghaH a Dich ghotpu scattered abroad je dispersed among the ghotpu' Daq Hoch the provinces vo' lIj kingdom, je chaj laws 'oH different than latlh people's. chaH yImev pol the joH laws. vaj 'oH ghaH ghobe' vaD the joH profit Daq allow chaH Daq remain.",
        9: "chugh 'oH pleases the joH, chaw' 'oH taH ghItlhta' vetlh chaH taH Qaw'ta'; je jIH DichDaq pay wa'maH SaD talents vo' baS chIS Daq the ghopmey vo' chaH 'Iv 'oH Daq yov vo' the joH business, Daq qem 'oH Daq the joH treasuries.”",
        10: "The joH tlhapta' Daj ring vo' Daj ghop, je nobta' 'oH Daq Haman the puqloD vo' Hammedatha the Agagite, the Jews' jagh.",
        11: "The joH ja'ta' Daq Haman, “The baS chIS ghaH nobpu' Daq SoH, the ghotpu je, Daq ta' tlhej chaH as 'oH seems QaQ Daq SoH.”",
        12: "vaj the joH scribes were ja' Daq Daq the wa'Dich jar, Daq the thirteenth jaj vo' the jar; je Hoch vetlh Haman ra'ta' ghaHta' ghItlhta' Daq the joH satraps, je Daq the governors 'Iv were Dung Hoch province, je Daq the joHHom vo' Hoch ghotpu, Daq Hoch province according its writing, je Daq Hoch ghotpu Daq chaj language. 'oH ghaHta' ghItlhta' Daq the pong vo' joH Ahasuerus, je 'oH ghaHta' sealed tlhej the joH ring.",
        13: "Letters were ngeHta' Sum couriers Daq Hoch the joH provinces, Daq Qaw', Daq HoH, je Daq cause Daq chIlqu', Hoch Jews, both Qup je qan, mach puqpu' je be'pu', Daq wa' jaj, 'ach Daq the thirteenth jaj vo' the twelfth jar, nuq ghaH the jar Adar, je Daq plunder chaj possessions.",
        14: "A copy vo' the letter, vetlh the decree should taH nobpu' pa' Daq Hoch province, ghaHta' published Daq Hoch the ghotpu', vetlh chaH should taH ready Daq vetlh jaj.",
        15: "The couriers mejta' vo' Daq haste Sum the joH ra'ta'ghach mu', je the decree ghaHta' nobpu' pa' Daq the citadel vo' Susa. The joH je Haman ba'ta' bIng Daq tlhutlh; 'ach the veng vo' Shushan ghaHta' perplexed.",
    },
    4: {
        1: "DaH ghorgh Mordecai tu'ta' pa' Hoch vetlh ghaHta' ta'pu', Mordecai tore Daj clothes, je lan Daq sackcloth tlhej ashes, je mejta' pa' Daq the midst vo' the veng, je wailed loudly je a bitterly.",
        2: "ghaH ghoSta' 'ach qaSpa' the joH lojmIt, vaD ghobe' wa' ghaH allowed inside the joH lojmIt clothed tlhej sackcloth.",
        3: "Daq Hoch province, wherever the joH ra'ta'ghach mu' je Daj decree ghoSta', pa' ghaHta' Dun mourning among the Jews, je fasting, je weeping, je wailing; je law' lay Daq sackcloth je ashes.",
        4: "Esther's maidens je Daj eunuchs ghoSta' je ja'ta' Daj vam, je the queen ghaHta' exceedingly grieved. ghaH ngeHta' Sut Daq Mordecai, Daq replace Daj sackcloth; 'ach ghaH ta'be' Hev 'oH.",
        5: "vaj Esther ja' vaD Hathach, wa' vo' the joH eunuchs, 'Iv ghaH ghajta' wIv Daq attend Daj, je ra'ta' ghaH Daq jaH Daq Mordecai, Daq tu' pa' nuq vam ghaHta', je qatlh 'oH ghaHta'.",
        6: "vaj Hathach mejta' pa' Daq Mordecai, Daq veng square nuq ghaHta' qaSpa' the joH lojmIt.",
        7: "Mordecai ja'ta' ghaH vo' Hoch vetlh ghajta' qaSta' Daq ghaH, je the exact sum vo' the Huch vetlh Haman ghajta' promised Daq pay Daq the joH treasuries vaD the QIH vo' the Jews.",
        8: "ghaH je nobta' ghaH the copy vo' the writing vo' the decree vetlh ghaHta' nobpu' pa' Daq Shushan Daq Qaw' chaH, Daq cha' 'oH Daq Esther, je Daq declare 'oH Daq Daj, je Daq urge Daj Daq jaH Daq Daq the joH, Daq chenmoH supplication Daq ghaH, je Daq chenmoH request qaSpa' ghaH, vaD Daj ghotpu.",
        9: "Hathach ghoSta' je ja'ta' Esther the mu'mey vo' Mordecai.",
        10: "vaj Esther jatlhta' Daq Hathach, je nobta' ghaH a message Daq Mordecai:",
        11: "“Hoch the joH toy'wI'pu', je the ghotpu vo' the joH provinces, Sov, vetlh 'Iv, whether loD joq be', choltaH Daq the joH Daq the inner bo'DIj Hutlh taH ja', pa' ghaH wa' chut vaD ghaH, vetlh ghaH taH lan Daq Hegh, except chaH Daq 'Iv the joH might 'uch pa' the golden scepter, vetlh ghaH may yIn. jIH ghaj ghobe' taH ja' Daq ghoS Daq Daq the joH Dochvammey wejmaH jajmey.”",
        12: "chaH ja'ta' Daq Mordecai Esther's mu'mey.",
        13: "vaj Mordecai tlhobta' chaH chegh jang Daq Esther, “yImev think Daq SoH'egh vetlh SoH DichDaq escape Daq the joH tuq vay' latlh than Hoch the Jews.",
        14: "vaD chugh SoH remain tam DaH, vaj relief je deliverance DichDaq ghoS Daq the Jews vo' another Daq, 'ach SoH je lIj vav tuq DichDaq chIlqu'. 'Iv SovtaH chugh SoH ghajbe' ghoS Daq the kingdom vaD such a poH as vam?”",
        15: "vaj Esther tlhobta' chaH Daq jang Mordecai,",
        16: "“jaH, tay'moH tay' Hoch the Jews 'Iv 'oH present Daq Shushan, je fast vaD jIH, je ghobe' Sop ghobe' tlhutlh wej jajmey, ram joq jaj. jIH je wIj maidens DichDaq je fast the rap way. vaj jIH DichDaq jaH Daq Daq the joH, nuq ghaH Daq the chut; je chugh jIH chIlqu', jIH chIlqu'.”",
        17: "vaj Mordecai mejta' Daj way, je ta'ta' according Daq Hoch vetlh Esther ghajta' ra'ta' ghaH.",
    },
    5: {
        1: "DaH 'oH qaSta' Daq the wejDIch jaj vetlh Esther lan Daq Daj royal Sut, je Qampu' Daq the inner bo'DIj vo' the joH tuq, next Daq the joH tuq. The joH ba'ta' Daq Daj royal quS'a' Daq the royal tuq, next Daq the entrance vo' the tuq.",
        2: "ghorgh the joH leghta' Esther the queen standing Daq the bo'DIj, ghaH obtained favor Daq Daj leghpu'; je the joH held pa' Daq Esther the golden scepter vetlh ghaHta' Daq Daj ghop. vaj Esther ghoSta' Sum, je touched the top vo' the scepter.",
        3: "vaj the joH tlhobta' Daj, “nuq would SoH rur, queen Esther? nuq ghaH lIj request? 'oH DIchDaq taH nobpu' SoH 'ach Daq the bID vo' the kingdom.”",
        4: "Esther ja'ta', “chugh 'oH seems QaQ Daq the joH, chaw' the joH je Haman ghoS DaHjaj Daq the banquet vetlh jIH ghaj prepared vaD ghaH.”",
        5: "vaj the joH ja'ta', “qem Haman quickly, vaj vetlh 'oH may taH ta'pu' as Esther ghajtaH ja'ta'.” vaj the joH je Haman ghoSta' Daq the banquet vetlh Esther ghajta' prepared.",
        6: "The joH ja'ta' Daq Esther Daq the banquet vo' HIq, “nuq ghaH lIj petition? 'oH DIchDaq taH granted SoH. nuq ghaH lIj request? 'ach Daq the bID vo' the kingdom 'oH DIchDaq taH performed.”",
        7: "vaj Esther jangta' je ja'ta', “wIj petition je wIj request ghaH vam.",
        8: "chugh jIH ghaj tu'ta' favor Daq the leghpu' vo' the joH, je chugh 'oH please the joH Daq grant wIj petition je Daq perform wIj request, chaw' the joH je Haman ghoS Daq the banquet vetlh jIH DichDaq ghuH vaD chaH, je jIH DichDaq ta' wa'leS as the joH ghajtaH ja'ta'.”",
        9: "vaj Haman mejta' pa' vetlh jaj joyful je Quchqu' vo' tIq, 'ach ghorgh Haman leghta' Mordecai Daq the joH lojmIt, vetlh ghaH ta'be' Qam Dung ghobe' vIH vaD ghaH, ghaH ghaHta' tebta' tlhej QeHpu' Daq Mordecai.",
        10: "Nevertheless Haman restrained himself, je mejta' home. pa', ghaH ngeHta' je ja' vaD Daj friends je Zeresh Daj be'nal.",
        11: "Haman recounted Daq chaH the batlh vo' Daj riches, the qevmey vo' Daj puqpu', Hoch the Dochmey Daq nuq the joH ghajta' promoted ghaH, je chay' ghaH ghajta' advanced ghaH Dung the joHHom je toy'wI'pu' vo' the joH.",
        12: "Haman je ja'ta', “HIja', Esther the queen chaw' ghobe' loD ghoS Daq tlhej the joH Daq the banquet vetlh ghaH ghajta' prepared 'ach jIH'egh; je wa'leS jIH 'oH je invited Sum Daj tay' tlhej the joH.",
        13: 'Yet Hoch vam avails jIH pagh, vaj tIq as jIH legh Mordecai the Jew sitting Daq the joH lojmIt.”',
        14: "vaj Zeresh Daj taH'nal je Hoch Daj friends ja'ta' Daq ghaH, “chaw' a gallows be chenmoHta' vaghmaH cubits jen, je Daq the po jatlh Daq the joH about hanging Mordecai Daq 'oH. vaj jaH Daq merrily tlhej the joH Daq the banquet.” vam pleased Haman, vaj ghaH ghajta' the gallows chenmoHta'.",
    },
    6: {
        1: "Daq vetlh ram, the joH couldn't Qong. ghaH ra'ta' the paq vo' records vo' the chronicles Daq taH qempu', je chaH were read Daq the joH.",
        2: "'oH ghaHta' tu'ta' ghItlhta' vetlh Mordecai ghajta' ja'ta' vo' Bigthana je Teresh, cha' vo' the joH eunuchs, 'Iv were doorkeepers, 'Iv ghajta' tried Daq lay ghopmey Daq the joH Ahasuerus.",
        3: "The joH ja'ta', “nuq quv je dignity ghajtaH taH bestowed Daq Mordecai vaD vam?” vaj the joH toy'wI'pu' 'Iv attended ghaH ja'ta', “pagh ghajtaH taH ta'pu' vaD ghaH.”",
        4: "The joH ja'ta', “'Iv ghaH Daq the bo'DIj?” DaH Haman ghajta' ghoS Daq the outer bo'DIj vo' the joH tuq, Daq jatlh Daq the joH about hanging Mordecai Daq the gallows vetlh ghaH ghajta' prepared vaD ghaH.",
        5: "The joH toy'wI'pu' ja'ta' Daq ghaH, “yIlegh, Haman stands Daq the bo'DIj.” The joH ja'ta', “chaw' ghaH ghoS Daq.”",
        6: "vaj Haman ghoSta' Daq. The joH ja'ta' Daq ghaH, “nuq DIchDaq taH ta'pu' Daq the loD 'Iv the joH delights Daq quv?” DaH Haman ja'ta' Daq Daj tIq, “'Iv would the joH tIv Daq quv latlh than jIH'egh?”",
        7: "Haman ja'ta' Daq the joH, “vaD the loD 'Iv the joH delights Daq quv,",
        8: "chaw' royal Sut taH qempu' nuq the joH uses Daq wear, je the horse vetlh the joH rides Daq, je Daq the nach vo' nuq a crown royal ghaH cher.",
        9: "chaw' the Sut je the horse taH toDta' Daq the ghop vo' wa' vo' the joH HochHom noble joHHom, vetlh chaH may array the loD 'Iv the joH delights Daq quv tlhej chaH, je ghaj ghaH ride Daq horseback vegh the veng square, je proclaim qaSpa' ghaH, ‘Thus DIchDaq 'oH taH ta'pu' Daq the loD 'Iv the joH delights Daq quv!'”",
        10: "vaj the joH ja'ta' Daq Haman, “Hurry je tlhap the Sut je the horse, as SoH ghaj ja'ta', je ta' vam vaD Mordecai the Jew, 'Iv sits Daq the joH lojmIt. chaw' pagh fail vo' Hoch vetlh SoH ghaj jatlhpu'.”",
        11: "vaj Haman tlhapta' the Sut je the horse, je arrayed Mordecai, je ghajta' ghaH ride vegh the veng square, je proclaimed qaSpa' ghaH, “Thus DIchDaq 'oH taH ta'pu' Daq the loD 'Iv the joH delights Daq quv!”",
        12: "Mordecai ghoSta' DoH Daq the joH lojmIt, 'ach Haman hurried Daq Daj tuq, mourning je ghajtaH Daj nach covered.",
        13: "Haman recounted Daq Zeresh Daj be'nal je Hoch Daj friends everything vetlh ghajta' qaSta' Daq ghaH. vaj Daj val loDpu' je Zeresh Daj be'nal ja'ta' Daq ghaH, “chugh Mordecai, qaSpa' 'Iv SoH ghaj begun Daq pum, ghaH vo' Jewish descent, SoH DichDaq ghobe' prevail Daq ghaH, 'ach SoH DichDaq DIch pum qaSpa' ghaH.”",
        14: "qaStaHvIS chaH were yet talking tlhej ghaH, the joH eunuchs ghoSta', je hurried Daq qem Haman Daq the banquet vetlh Esther ghajta' prepared.",
    },
    7: {
        1: "vaj the joH je Haman ghoSta' Daq banquet tlhej Esther the queen.",
        2: "The joH ja'ta' again Daq Esther Daq the cha'DIch jaj Daq the banquet vo' HIq, “nuq ghaH lIj petition, queen Esther? 'oH DIchDaq taH granted SoH. nuq ghaH lIj request? 'ach Daq the bID vo' the kingdom 'oH DIchDaq taH performed.”",
        3: "vaj Esther the queen jangta', “chugh jIH ghaj tu'ta' favor Daq lIj leghpu', toH joH, je chugh 'oH please the joH, chaw' wIj yIn taH nobpu' jIH Daq wIj petition, je wIj ghotpu Daq wIj request.",
        4: "vaD maH 'oH sold, jIH je wIj ghotpu, Daq taH Qaw'ta', Daq taH Heghta', je Daq chIlqu'. 'ach chugh maH ghajta' taH sold vaD bondservants je bondmaids, jIH would ghaj held wIj roj, although the jagh laH ghobe' ghaj compensated vaD the joH loss.”",
        5: "vaj joH Ahasuerus ja'ta' Daq Esther the queen, “'Iv ghaH ghaH, je nuqDaq ghaH ghaH 'Iv dared presume Daq Daj tIq Daq ta' vaj?”",
        6: "Esther ja'ta', “An jagh je an jagh, 'ach vam mIgh Haman!” vaj Haman ghaHta' vIp qaSpa' the joH je the queen.",
        7: "The joH Hu' Daq Daj QeHpu' vo' the banquet vo' HIq je mejta' Daq the palace wIjghachHom. Haman Qampu' Dung Daq chenmoH request vaD Daj yIn Daq Esther the queen; vaD ghaH leghta' vetlh pa' ghaHta' mIghtaHghach determined Daq ghaH Sum the joH.",
        8: "vaj the joH cheghta' pa' vo' the palace wIjghachHom Daq the Daq vo' the banquet vo' HIq; je Haman ghajta' fallen Daq the couch nuqDaq Esther ghaHta'. vaj the joH ja'ta', “DichDaq ghaH 'ach assault the queen Daq front vo' jIH Daq the tuq?” As the mu' mejta' pa' vo' the joH nujDu', chaH covered Haman's qab.",
        9: "vaj Harbonah, wa' vo' the eunuchs 'Iv were tlhej the joH ja'ta', “yIlegh, the gallows vaghmaH cubits jen, nuq Haman ghajtaH chenmoHta' vaD Mordecai, 'Iv jatlhta' QaQ vaD the joH, ghaH standing Daq Haman's tuq.” The joH ja'ta', “Hang ghaH Daq 'oH!”",
        10: "vaj chaH hanged Haman Daq the gallows vetlh ghaH ghajta' prepared vaD Mordecai. vaj ghaHta' the joH QeHpu' pacified.",
    },
    8: {
        1: "Daq vetlh jaj, joH Ahasuerus nobta' the tuq vo' Haman, the Jews' jagh, Daq Esther the queen. Mordecai ghoSta' qaSpa' the joH; vaD Esther ghajta' ja'ta' nuq ghaH ghaHta' Daq Daj.",
        2: "The joH tlhapta' litHa' Daj ring, nuq ghaH ghajta' tlhappu' vo' Haman, je nobta' 'oH Daq Mordecai. Esther cher Mordecai Dung the tuq vo' Haman.",
        3: "Esther jatlhta' yet again qaSpa' the joH, je pumta' bIng Daq Daj qamDu', je begged ghaH tlhej tears Daq lan DoH the mischief vo' Haman the Agagite, je Daj device vetlh ghaH ghajta' devised Daq the Jews.",
        4: "vaj the joH held pa' Daq Esther the golden scepter. vaj Esther Hu', je Qampu' qaSpa' the joH.",
        5: "ghaH ja'ta', “chugh 'oH pleases the joH, je chugh jIH ghaj tu'ta' favor Daq Daj leghpu', je the Doch seem nIH Daq the joH, je jIH 'oH pleasing Daq Daj mInDu', chaw' 'oH taH ghItlhta' Daq reverse the letters devised Sum Haman, the puqloD vo' Hammedatha the Agagite, nuq ghaH wrote Daq Qaw' the Jews 'Iv 'oH Daq Hoch the joH provinces.",
        6: "vaD chay' laH jIH SIQ Daq legh the mIghtaHghach vetlh would ghoS Daq wIj ghotpu? chay' laH jIH SIQ Daq legh the QIH vo' wIj relatives?”",
        7: "vaj joH Ahasuerus ja'ta' Daq Esther the queen je Daq Mordecai the Jew, “legh, jIH ghaj nobpu' Esther the tuq vo' Haman, je ghaH chaH ghaj hanged Daq the gallows, because ghaH laid Daj ghop Daq the Jews.",
        8: "Write je Daq the Jews, as 'oH pleases SoH, Daq the joH pong, je seal 'oH tlhej the joH ring; vaD the writing nuq ghaH ghItlhta' Daq the joH pong, je sealed tlhej the joH ring, may ghobe' taH reversed Sum vay' loD.”",
        9: "vaj the joH scribes were ja' Daq vetlh poH, Daq the wejDIch jar Sivan, Daq the cha'maH- wejDIch jaj vo' the jar; je 'oH ghaHta' ghItlhta' according Daq Hoch vetlh Mordecai ra'ta' Daq the Jews, je Daq the satraps, je the governors je joHHom vo' the provinces nuq 'oH vo' India Daq Ethiopia, wa' vatlh cha'maH- Soch provinces, Daq Hoch province according Daq its writing, je Daq Hoch ghotpu Daq chaj language, je Daq the Jews Daq chaj writing, je Daq chaj language.",
        10: "ghaH wrote Daq the pong vo' joH Ahasuerus, je sealed 'oH tlhej the joH ring, je ngeHta' letters Sum courier Daq horseback, riding Daq royal horses vetlh were tIr Soj vo' swift steeds.",
        11: "Daq chaH letters, the joH granted the Jews 'Iv were Daq Hoch veng Daq tay'moH themselves tay', je Daq defend chaj yIn, Daq Qaw', Daq HoH, je Daq cause Daq chIlqu', Hoch the HoS vo' the ghotpu je province vetlh would assault chaH, chaj mach ones je be'pu', je Daq plunder chaj possessions,",
        12: "Daq wa' jaj Daq Hoch the provinces vo' joH Ahasuerus, Daq the thirteenth jaj vo' the twelfth jar, nuq ghaH the jar Adar.",
        13: "A copy vo' the letter, vetlh the decree should taH nobpu' pa' Daq Hoch province, ghaHta' published Daq Hoch the ghotpu', vetlh the Jews should taH ready vaD vetlh jaj Daq bortaS themselves Daq chaj jaghpu'.",
        14: "vaj the couriers 'Iv rode Daq royal horses mejta' pa', hastened je pressed Daq Sum the joH ra'ta'ghach mu'. The decree ghaHta' nobpu' pa' Daq the citadel vo' Susa.",
        15: "Mordecai mejta' pa' vo' the Daq vo' the joH Daq royal Sut vo' blue je chIS, je tlhej a Dun crown vo' SuD baS, je tlhej a robe vo' fine linen je purple; je the veng vo' Susa jachta' je ghaHta' Quchqu'.",
        16: "The Jews ghajta' wov, Quchqu'taHghach, Quch, je quv.",
        17: "Daq Hoch province, je Daq Hoch veng, wherever the joH ra'ta'ghach mu' je Daj decree ghoSta', the Jews ghajta' Quchqu'taHghach, Quch, a 'uQ'a', je a QaQ jaj. law' vo' among the ghotpu' vo' the puH mojta' Jews; vaD the taHvIp vo' the Jews ghaHta' fallen Daq chaH.",
    },
    9: {
        1: "DaH Daq the twelfth jar, nuq ghaH the jar Adar, Daq the thirteenth jaj vo' the jar, ghorgh the joH ra'ta'ghach mu' je Daj decree drew Sum Daq taH lan Daq execution, Daq the jaj vetlh the jaghpu' vo' the Jews hoped Daq chargh chaH, ('ach 'oH ghaHta' tlhe'ta' pa' the opposite qaSta', vetlh the Jews conquered chaH 'Iv hated chaH),",
        2: "the Jews boSta' themselves tay' Daq chaj vengmey throughout Hoch the provinces vo' the joH Ahasuerus, Daq lay ghopmey Daq chaH 'Iv wanted Daq harm chaH. ghobe' wa' laH withstand chaH, because the taHvIp vo' chaH ghajta' fallen Daq Hoch the ghotpu.",
        3: "Hoch the joHHom vo' the provinces, the satraps, the governors, je chaH 'Iv ta'ta' the joH business helped the Jews, because the taHvIp vo' Mordecai ghajta' fallen Daq chaH.",
        4: "vaD Mordecai ghaHta' Dun Daq the joH tuq, je Daj fame mejta' pa' throughout Hoch the provinces; vaD the loD Mordecai grew greater je greater.",
        5: "The Jews struck Hoch chaj jaghpu' tlhej the stroke vo' the 'etlh, je tlhej HoHqu' je QIH, je ta'ta' nuq chaH wanted Daq chaH 'Iv hated chaH.",
        6: "Daq the citadel vo' Susa, the Jews HoHta' je Qaw'ta' vagh vatlh loDpu'.",
        7: "chaH HoHta' Parshandatha, Dalphon, Aspatha,",
        8: 'Poratha, Adalia, Aridatha,',
        9: 'Parmashta, Arisai, Aridai, je Vaizatha,',
        10: "the wa'maH puqloDpu' vo' Haman the puqloD vo' Hammedatha, the Jew's jagh, 'ach chaH ta'be' lay chaj ghop Daq the plunder.",
        11: "Daq vetlh jaj, the mI' vo' chaH 'Iv were Heghta' Daq the citadel vo' Susa ghaHta' qempu' qaSpa' the joH.",
        12: "The joH ja'ta' Daq Esther the queen, “The Jews ghaj Heghta' je Qaw'ta' vagh vatlh loDpu' Daq the citadel vo' Susa, including the wa'maH puqloDpu' vo' Haman; nuq vaj ghaj chaH ta'pu' Daq the leS vo' the joH provinces! DaH nuq ghaH lIj petition? 'oH DIchDaq taH granted SoH. nuq ghaH lIj further request? 'oH DIchDaq taH ta'pu'.”",
        13: "vaj Esther ja'ta', “chugh 'oH pleases the joH, chaw' 'oH taH granted Daq the Jews 'Iv 'oH Daq Shushan Daq ta' wa'leS je according Daq vam jaj decree, je chaw' Haman's wa'maH puqloDpu' taH hanged Daq the gallows.”",
        14: "The joH ra'ta' vam Daq taH ta'pu'. A decree ghaHta' nobpu' pa' Daq Shushan; je chaH hanged Haman's wa'maH puqloDpu'.",
        15: "The Jews 'Iv were Daq Shushan boSta' themselves tay' Daq the fourteenth jaj je vo' the jar Adar, je HoHta' wej vatlh loDpu' Daq Shushan; 'ach chaH ta'be' lay chaj ghop Daq the non.",
        16: "The latlh Jews 'Iv were Daq the joH provinces boSta' themselves tay', defended chaj yIn, ghajta' leS vo' chaj jaghpu', je HoHta' seventy- vagh SaD vo' chaH 'Iv hated chaH; 'ach chaH ta'be' lay chaj ghop Daq the plunder.",
        17: "vam ghaHta' ta'pu' Daq the thirteenth jaj vo' the jar Adar; je Daq the fourteenth jaj vo' vetlh jar chaH rested je chenmoHta' 'oH a jaj vo' feasting je Quchqu'taHghach.",
        18: "'ach the Jews 'Iv were Daq Shushan assembled tay' Daq the thirteenth je Daq the fourteenth jajmey vo' the jar; je Daq the fifteenth jaj vo' vetlh jar, chaH rested, je chenmoHta' 'oH a jaj vo' feasting je Quchqu'taHghach.",
        19: "vaj the Jews vo' the villages, 'Iv yIn Daq the unwalled towns, chenmoH the fourteenth jaj vo' the jar Adar a jaj vo' Quchqu'taHghach je feasting, a QaQ jaj, je a jaj vo' sending presents vo' Soj Daq wa' another.",
        20: "Mordecai wrote Dochvammey Dochmey, je ngeHta' letters Daq Hoch the Jews 'Iv were Daq Hoch the provinces vo' the joH Ahasuerus, both Sum je Hop,",
        21: "Daq enjoin chaH vetlh chaH should pol the fourteenth je fifteenth jajmey vo' the jar Adar yearly,",
        22: "as the jajmey Daq nuq the Jews ghajta' leS vo' chaj jaghpu', je the jar nuq ghaHta' tlhe'ta' Daq chaH vo' QoSqu' Daq Quchqu'taHghach, je vo' mourning Daq a QaQ jaj; vetlh chaH should chenmoH chaH jajmey vo' feasting je Quchqu'taHghach, je vo' sending presents vo' Soj Daq wa' another, je gifts Daq the needy.",
        23: "The Jews accepted the custom vetlh chaH ghajta' begun, as Mordecai ghajta' ghItlhta' Daq chaH;",
        24: "because Haman the puqloD vo' Hammedatha, the Agagite, the jagh vo' Hoch the Jews, ghajta' plotted Daq the Jews Daq Qaw' chaH, je ghajta' chuH “Pur,” vetlh ghaH the lot, Daq consume chaH, je Daq Qaw' chaH;",
        25: "'ach ghorgh vam mojta' Sovta' Daq the joH, ghaH ra'ta' Sum letters vetlh Daj mIgh device, nuq ghaH ghajta' devised Daq the Jews, should chegh Daq Daj ghaj nach, je vetlh ghaH je Daj puqloDpu' should taH hanged Daq the gallows.",
        26: "vaj chaH ja' Dochvammey jajmey “Purim, { Note: Purim ghaH the Hebrew plural vaD pur, nuq means lot. }” vo' the mu' “Pur.” vaj because vo' Hoch the mu'mey vo' vam letter, je vo' vetlh nuq chaH ghajta' leghpu' concerning vam matter, je vetlh nuq ghajta' ghoS Daq chaH,",
        27: "the Jews established, je imposed Daq themselves, je Daq chaj descendants, je Daq Hoch chaH 'Iv joined themselves Daq chaH, vaj vetlh 'oH should ghobe' fail, vetlh chaH would pol Dochvammey cha' jajmey according Daq nuq ghaHta' ghItlhta', je according Daq its wIv poH, Hoch DIS;",
        28: "je vetlh Dochvammey jajmey should taH remembered je polta' throughout Hoch generation, Hoch qorDu', Hoch province, je Hoch veng; je vetlh Dochvammey jajmey vo' Purim should ghobe' fail vo' among the Jews, ghobe' the memory vo' chaH chIlqu' vo' chaj tIr.",
        29: "vaj Esther the queen, the puqbe' vo' Abihail, je Mordecai the Jew, wrote tlhej Hoch authority Daq confirm vam cha'DIch letter vo' Purim.",
        30: "ghaH ngeHta' letters Daq Hoch the Jews, Daq the vatlh cha'maH- Soch provinces vo' the kingdom vo' Ahasuerus, tlhej mu'mey vo' roj je vIt,",
        31: "Daq confirm Dochvammey jajmey vo' Purim Daq chaj wIv poHmey, as Mordecai the Jew je Esther the queen ghajta' decreed, je as chaH ghajta' imposed upon themselves je chaj descendants, Daq the matter vo' the fastings je chaj SaQ.",
        32: "The ra'ta'ghach mu' vo' Esther confirmed Dochvammey matters vo' Purim; je 'oH ghaHta' ghItlhta' Daq the paq.",
    },
    10: {
        1: "joH Ahasuerus laid a tribute Daq the puH, je Daq the islands vo' the biQ'a'.",
        2: "Hoch the ta'mey vo' Daj HoS je vo' Daj might, je the teblu'ta' account vo' the greatness vo' Mordecai, Daq nuq the joH advanced ghaH, aren't chaH ghItlhta' Daq the paq vo' the chronicles vo' the joHpu' vo' Media je Persia?",
        3: "vaD Mordecai the Jew ghaHta' next Daq joH Ahasuerus, je Dun among the Jews, je accepted Sum the qevmey vo' Daj loDnI'pu', seeking the QaQ vo' Daj ghotpu, je speaking roj Daq Hoch Daj descendants.",
    },
}
